private func checkBase64(_ base64: String, _ data: Data) -> Bool {
    // Replace `&#61;&#61;` with `==`. No need to parse all XML/HTML unicode entities.
    let sanitized = if let match = base64.firstMatch(of: /&#61;&#61;$/) {
        base64.replacingCharacters(in: match.range, with: "==")
    } else if let match = base64.firstMatch(of: /&#61;$/) {
        base64.replacingCharacters(in: match.range, with: "=")
    } else {
        base64
    }

    // Check that data matches
    guard let utf8Data = sanitized.data(using: .utf8) else {
        return false
    }
    let data2 = Data(base64Encoded: utf8Data)
    return data == data2
}
